/*
f( M )
                    where
                    M: ℝ^( k×k )
                    f: ℝ^( k×k ) -> ℝ 
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT ret;

    heartlib(
        const Eigen::MatrixXd & M,
        const std::function<double(Eigen::MatrixXd)> & f)
    {
        const long k = M.cols();
        assert( M.rows() == k );
        ret = f((M).eval());
    }
};

